    "pub_date": "2026-08-23 13:26:15",
    "author": "郭琳",
    "description": "《参考消息》8月23日刊发美国《华尔街日报》网站报道《中国汽车出口激增，运输船一船难求》。 中国汽车厂商正在生产大量用于出口的汽车，全球航运业的运力已经跟不上了。专用汽车运输船如同一座座漂浮的停车场，将汽车从中国工厂运往海外的运输船船期已排到几年之后。 据预测，今年中国汽车出口量最高可能达到1000万辆。 新华社音视频部制作",
    "content": "《参考消息》8月23日刊发美国《华尔街日报》网站报道《中国汽车出口激增，运输船一船难求》。 中国汽车厂商正在生产大量用于出口的汽车，全球航运业的运力已经跟不上了。专用汽车运输船如同一座座漂浮的停车场，将汽车从中国工厂运往海外的运输船船期已排到几年之后。 据预测，今年中国汽车出口量最高可能达到1000万辆。 新华社音视频部制作"
