    "author": "刘曼婷（加州大学洛杉矶分校古典学系）",
    "description": "渺小的英雄与巨人、狡智（μῆτις）与暴力的鲜明对比，使独眼巨人神话成为《奥德赛》诸多故事中尤为脍炙人口的一篇。在《奥德赛》原诗中，当历经十年艰险航程、失去了所有同伴的奥德修斯向款待他的费埃克斯人讲述他是什么人、他又有什么事迹时，诗人让奥德修斯提供的第一个长篇叙事，便是他与独眼巨人波吕斐摩斯的斗智。 不难想见，对于已经被独眼巨人劫掠过、并且因此被迫背井离乡的费埃克斯人（参见《奥德赛》6.3-6）而言，这个故事能极富说服力地证明眼前英雄的…",
    "content": "渺小的英雄与巨人、狡智（μῆτις）与暴力的鲜明对比，使独眼巨人神话成为《奥德赛》诸多故事中尤为脍炙人口的一篇。在《奥德赛》原诗中，当历经十年艰险航程、失去了所有同伴的奥德修斯向款待他的费埃克斯人讲述他是什么人、他又有什么事迹时，诗人让奥德修斯提供的第一个长篇叙事，便是他与独眼巨人波吕斐摩斯的斗智。 不难想见，对于已经被独眼巨人劫掠过、并且因此被迫背井离乡的费埃克斯人（参见《奥德赛》6.3-6）而言，这个故事能极富说服力地证明眼前英雄的品性：语言机敏、计谋高明，且富有勇力。可是，巨人不仅是英雄的背景板：无论在《奥德…"
