    "content": "新华社内罗毕8月22日电 通讯｜科技之“眼”助力肯尼亚野生动物保护 新华社记者由荟圆 刘琼 王灏 在肯尼亚马赛马拉国家保护区内一片位于马拉河岸边的区域，伴随着一阵嗡鸣声，一架中国大疆无人机平稳升空，掠过起伏的草地和灌木丛，飞向远处。 巡护员阿尔弗雷德·贝特正在用无人机进行巡查。随着他用遥控器不断调整无人机飞行方向，蜿蜒的河道、岸边的河马和草原上的角马群逐一出现在传回的实时画面上。一些因地形阻隔而在地面上难以观察的区域，也通过无人机的视角清晰呈现出来。 贝特介绍，目前已有3架大疆无人机用于马赛马拉国家保护区的巡护工作…"
