    "pub_date": "2026-08-23 12:59:51",
    "author": "澎湃新闻高级记者 李佳蔚",
    "description": "2026年8月23日，澎湃新闻记者从复旦大学附属中山医院樊嘉院士团队获悉，该团队近日联合国内24家大型肝胆肿瘤中心完成的一项全国多中心Ⅲ期随机对照研究，为部分局部晚期肝癌患者提供了新的治疗证据。 研究显示，对于接受阿替利珠单抗联合贝伐珠单抗治疗后肿瘤得到控制、并具备手术切除条件的患者，手术切除并在术后继续系统治疗，相比持续药物治疗，可显著延长患者的治疗至失败时间。2026年8月22日，该成果发表在国际顶级医学期刊《柳叶刀》（The La…",
    "content": "2026年8月23日，澎湃新闻记者从复旦大学附属中山医院樊嘉院士团队获悉，该团队近日联合国内24家大型肝胆肿瘤中心完成的一项全国多中心Ⅲ期随机对照研究，为部分局部晚期肝癌患者提供了新的治疗证据。 研究显示，对于接受阿替利珠单抗联合贝伐珠单抗治疗后肿瘤得到控制、并具备手术切除条件的患者，手术切除并在术后继续系统治疗，相比持续药物治疗，可显著延长患者的治疗至失败时间。2026年8月22日，该成果发表在国际顶级医学期刊《柳叶刀》（The Lancet）上。 相关成果于2026年8月22日发表在国际顶级医学期刊《柳叶刀》上…"
