    "content": "日本茨城县南部23日凌晨发生5.9级地震，东京震感明显。这是当天在日本东京拍摄的地震信息。新华社记者 贾浩成 摄 新华社东京8月23日电（记者李子越 陈泽安）据日本富士新闻网报道，23日凌晨发生在日本茨城县南部的5.9级地震已造成至少37人受伤，多地出现水管爆裂、交通受阻等情况。 日本富士新闻网援引日本总务省消防厅消息称，截至当天10时，地震已在东京都、茨城县、神奈川县等地造成至少37人受伤。其中，横滨市一名80多岁女性伤势严重。 受地震影响，日本关东地区部分铁路线路一度暂停运行，目前正在逐步恢复。东京都等地发生多…"
