    "content": "新华社比什凯克8月23日电（记者江宥林）《玛纳斯》歌舞剧日前在吉尔吉斯斯坦首都比什凯克国家音乐厅上演，来自中国新疆克孜勒苏柯尔克孜自治州歌舞团的演员为两国上千名观众倾情演绎了这部传奇史诗。 吉尔吉斯斯坦国务秘书科伊奇耶夫在活动上致辞说，文化是连接不同民族、促进民心相通的坚实桥梁。这类文化活动有助于密切两国文化交流，增进吉中人民友谊和相互了解。他表示，相信史诗《玛纳斯》能为进一步巩固双方友好关系提供助力。 中国驻吉尔吉斯斯坦大使刘江平表示，史诗《玛纳斯》是中吉两国共同的文化瑰宝，是双方人文交流的重要桥梁，是两国人民友…"
