    "description": "DeepSeek宣布于8月23日（周日）00:00起调整峰谷计费规则。调整后，周末（周六、周日）全天不再区分峰谷时段，统一按低谷时段价格收取调用费用。工作日（周一至周五）继续执行原有峰谷分段计费。新规则生效前产生的费用，仍按原计费标准结算。（界面）",
    "content": "DeepSeek宣布于8月23日（周日）00:00起调整峰谷计费规则。调整后，周末（周六、周日）全天不再区分峰谷时段，统一按低谷时段价格收取调用费用。工作日（周一至周五）继续执行原有峰谷分段计费。新规则生效前产生的费用，仍按原计费标准结算。（界面）"
