    "title": "渝昆高铁盐津南站进入冲刺阶段",
    "link": "http://www.news.cn/20260823/1eb62bd261d347988bbfc3925a249246/c.html",
    "pub_date": "2026-08-23 12:06:58",
    "author": "陆志秋（摄制）,熊轩昂",
    "description": "8月22日，渝昆高铁盐津南站挂牌，标志着渝昆高铁盐津南站建设进入冲刺阶段。盐津南站位于云南省昭通市盐津县庙坝镇黄草村，是渝昆高铁“出川入滇”第一站。 车站采用“站桥合一”设计，将站台与白水江四线特大桥有机融合，桥面距江面高达80米，最大桥墩高82米，站台即桥面。目前，站房装饰装修及机电设备安装已进入收尾冲刺阶段，建成后，盐津南站可同时容纳600名旅客换乘。 作者：熊轩昂 刘鑫 罗卓海 摄制：陆志秋 新华社音视频部制作",
    "content": "8月22日，渝昆高铁盐津南站挂牌，标志着渝昆高铁盐津南站建设进入冲刺阶段。盐津南站位于云南省昭通市盐津县庙坝镇黄草村，是渝昆高铁“出川入滇”第一站。 车站采用“站桥合一”设计，将站台与白水江四线特大桥有机融合，桥面距江面高达80米，最大桥墩高82米，站台即桥面。目前，站房装饰装修及机电设备安装已进入收尾冲刺阶段，建成后，盐津南站可同时容纳600名旅客换乘。 作者：熊轩昂 刘鑫 罗卓海 摄制：陆志秋 新华社音视频部制作"
