    "content": "快科技8月23日消息，8月22日，在2026中国首席经济学家复旦管院科创论坛上，蔚来创始人、董事长、CEO李斌针对中国新能源汽车产业发展，发表了自己的看法。 李斌称 ：“今年对于新能源汽车是非常重要的一年，整体竞争非常激烈，中国汽车行业也在进入四个新阶段。” 第一， 最残酷决赛阶段。接下来三五年，最后的玩家差不多就会尘埃落定。 一家车企到底能不能跟上？会不会被甩下？最近两年会是非常重要的一个时期。 第二，纯电渗透率加速爬升阶段。今年中国车市所有动力形式，其实只有纯电在增长，插混、增程包括纯燃油都在下跌。背后最根本的…"
