    "description": "我不会写代码。 过去两个月，我主要通过 AI Coding 做了一个叫 MarkOVO 的项目：把 PDF 、Word 、PPT 、等多格式文件统一转换成 Markdown ，支持 Web 、API 、CLI 和 MCP 四种使用方式。 Git 历史里累计新增了大约 101 万行内容。代码、测试和文档都由 AI 完成，我主要负责决定做什么，以及最后的结果能不能上线。 TL;DR：我的几个关键认识 AI 可以快速写出大量功能，但决定做什么…",
    "content": "我不会写代码。 过去两个月，我主要通过 AI Coding 做了一个叫 MarkOVO 的项目：把 PDF 、Word 、PPT 、等多格式文件统一转换成 Markdown ，支持 Web 、API 、CLI 和 MCP 四种使用方式。 Git 历史里累计新增了大约 101 万行内容。代码、测试和文档都由 AI 完成，我主要负责决定做什么，以及最后的结果能不能上线。 TL;DR：我的几个关键认识 AI 可以快速写出大量功能，但决定做什么、应该怎么做，比写出功能更重要。 哪怕是最强的 AI 模型，如果没有先设计好交互…"
