    "content": "1950年，第一届世界技能大赛在西班牙马德里举行。24名来自西班牙和葡萄牙的选手，只比了6个项目：钳工、木模制作、车工、电气绕组、铣工和家具制作。当时的世赛，就像是由车床、铣床和木工工具组成的技能车间。 76年后，这张技能清单已经从6项扩展到64项。9月22日至27日，第48届世界技能大赛（下简称“世赛”）将在上海举行。无人机系统、轨道车辆技术、软件测试、数字交互媒体设计、智慧安防技术等7个新项目，将首次登上世赛舞台。 世赛不仅是一场关乎国家荣誉、争夺金银铜牌的竞技比赛，也可以看作是一张不断变化的人类技能清单。什么…"
