    "description": "首先，我是楼上的住户。 楼下住户最近装修，拆了吊顶后发现楼上卫生间淋浴间地漏附近有水渗下去，周围有明显被水浸泡的痕迹。 昨天咸鱼找师傅过来看了一下，给我一个方案。似乎是用一种液体胶水混合水之后覆盖在瓷砖上，然后让液体顺着有缝隙的地方流进去，等到干固之后就能够把缝隙填充，解决渗水的问题。 不知道这个方案是不现在比较主流的一种方法，关于费用，他报价在 2000 元左右。 友友们有没有过类似的经历呀？ 关于这个价格和方案靠谱吗？ 拍的一张图片",
