    "title": "中阿启动干旱、荒漠化和土地退化防治五年行动计划",
    "link": "https://www.chinanews.com.cn/gn/2026/08-23/10682602.shtml",
    "pub_date": "2026-08-23 11:37:23",
    "author": "",
    "description": "中新社北京8月23日电 (记者 陈溯)记者23日从中国国家林业和草原局获悉，22日，中国-阿拉伯国家干旱、荒漠化和土地退化国际研究中心指导委员会第二次扩大会议暨中阿合作研讨会于《联合国防治荒漠化公约》第十七次缔约方大会期间，在蒙古国首都乌兰巴托召开，会议通过并正式发布《中阿干旱、荒漠化和土地退化防治五年行动计划》。",
