    "pub_date": "2026-08-23 11:12:15",
    "author": "",
    "description": "中新网宁波8月23日电 (丁斐煜 董满 王宁川)近日，华东某海域一艘渔船上1名渔民作业时不慎受伤。东部战区海军某部接到求救后，迅速部署指挥郑州舰、南通舰、千岛湖舰及驻舰直升机分队组成海空联合搜救兵力，成功将伤员转运救治。目前，受伤渔民生命体征已恢复平稳。",
    "content": "中新网宁波8月23日电 (丁斐煜 董满 王宁川)近日，华东某海域一艘渔船上1名渔民作业时不慎受伤。东部战区海军某部接到求救后，迅速部署指挥郑州舰、南通舰、千岛湖舰及驻舰直升机分队组成海空联合搜救兵力，成功将伤员转运救治。目前，受伤渔民生命体征已恢复平稳。"
