    "content": "新华社南宁8月23日电（记者杨驰、吴思思）记者从广西壮族自治区防汛抗旱指挥部获悉，鉴于自治区水文中心于8月23日0时发布洪水红色预警，经自治区防汛抗旱指挥部组织研判，根据《广西防汛抗旱应急预案》有关规定，决定于23日4时对防城港、崇左市将自治区防汛防台风（含地质灾害）应急响应提升至二级。 据自治区水文中心监测，8月23日0时，全区共有明江及支流思州河、派连河、公安河，左江上游平而河等5条河流8个水文站超警0.29米至4.78米，明江全线超警。 气象部门预测，受今年第19号台风（热带风暴级）影响，23日白天至24日夜…"
