    "content": "新华社贝尔格莱德8月23日电 综述｜美债收益率走高 欧洲债市承压加剧 新华社记者金丹依 近日，美国长期国债收益率升至近20年高位，致使欧洲债券市场持续受到影响。尽管美国财政部出手干预一度缓解美债抛售压力，但欧洲债市仍普遍承压。 21日，作为美国财政部回购目标之一的30年期美国国债收益率上行至5.273%；当周早些时候，这一收益率一度升至5.34%，创下2007年以来新高。欧洲主要国家国债收益率也同步走高。截至21日，德国10年期国债收益率徘徊在3.25%左右，逼近15年高位；法国10年期国债收益率升破4.13%，为…"
