    "content": "海报制作：吴彬尔 新华社北京8月23日电（记者张晓洁）经人力资源社会保障部批准，第48届世界技能大赛中国代表团近日正式成立。记者8月23日了解到，中国代表团共220人，其中包括71名参赛选手，将参加全部64个项目的比赛。参赛选手来自全国21个省份，其中学生49名、职工22名。选手平均年龄21岁，年龄最小的18岁，最大的25岁。 我国自2010年加入世界技能组织以来，已参加7届世界技能大赛，累计获得93枚金牌、41枚银牌、28枚铜牌和71个优胜奖，连续4届位居金牌榜、团体总分世界第一。 第48届世界技能大赛将于今年9…"
