    "description": "扎根毛乌素沙地的“治沙英雄”殷玉珍多年来一直牵挂着一位美国友人——罗纳德·萨科尔斯基（网络称其为赛考斯）。1999年“赛考斯”捐资5000美元支持殷玉珍治沙造林，如今已长成5万余棵林木。2000年殷玉珍和“赛考斯”曾在毛乌素沙地中相见，之后便失去联系。 今年5月中旬，殷玉珍发布视频，寻找当年捐资助她治沙的美国友人“赛考斯”，视频在互联网上引发广泛关注。 作者：彭源、达日罕、金泽成、张旭 新华社音视频部制作",
    "content": "扎根毛乌素沙地的“治沙英雄”殷玉珍多年来一直牵挂着一位美国友人——罗纳德·萨科尔斯基（网络称其为赛考斯）。1999年“赛考斯”捐资5000美元支持殷玉珍治沙造林，如今已长成5万余棵林木。2000年殷玉珍和“赛考斯”曾在毛乌素沙地中相见，之后便失去联系。 今年5月中旬，殷玉珍发布视频，寻找当年捐资助她治沙的美国友人“赛考斯”，视频在互联网上引发广泛关注。 作者：彭源、达日罕、金泽成、张旭 新华社音视频部制作"
