    "description": "2026年08月23日 本报北京8月22日电 （记者王观）记者从财政部获悉：今年以来，围绕持续挖掘内需潜力，财政部多措并举继续支持鼓励消费，下达消费品以旧换新资金1875亿元，带动相关商品销售额约1.32万亿元，惠及1.78亿人次。创新推出财政金融协同促内需一揽子政策，定向支持居民消费和消费行业经营主体，从供需两端同时发力，此项政策已惠及居民1.13亿人次。在50个试点城市开展有奖发票活动，带动相关领域销售额超3700亿元。 投资方面，…",
    "content": "2026年08月23日 本报北京8月22日电&nbsp;&nbsp;（记者王观）记者从财政部获悉：今年以来，围绕持续挖掘内需潜力，财政部多措并举继续支持鼓励消费，下达消费品以旧换新资金1875亿元，带动相关商品销售额约1.32万亿元，惠及1.78亿人次。创新推出财政金融协同促内需一揽子政策，定向支持居民消费和消费行业经营主体，从供需两端同时发力，此项政策已惠及居民1.13亿人次。在50个试点城市开展有奖发票活动，带动相关领域销售额超3700亿元。 投资方面，加快超长期特别国债发行使用，其中8000亿元“两重”资金已…"
